// Словарь красивых названий каналов
const channelNames = {
  'school21sber': 'Школа 21',
  'backend_baza': 'Backend База',
  'habr_com': 'Хабр',
  'bamrus': 'Бизнес-анализ & IT'
};

// Функция для форматирования даты
function formatDate(dateString) {
  if (!dateString) return new Date().toISOString().split('T')[0];
  try {
    const date = new Date(dateString);
    return date.toISOString().split('T')[0]; // YYYY-MM-DD
  } catch {
    return new Date().toISOString().split('T')[0];
  }
}

// Функция для форматирования даты и времени публикации
function formatPubDate(dateString) {
  if (!dateString) return new Date().toISOString().slice(0, 16).replace('T', ' ');
  try {
    const date = new Date(dateString);
    return date.toISOString().slice(0, 16).replace('T', ' '); // YYYY-MM-DD HH:MM
  } catch {
    return new Date().toISOString().slice(0, 16).replace('T', ' ');
  }
}

// Обработка входных данных
const items = $input.all();
const channelsMap = new Map();
const seenUrls = new Set();

// Группируем по источникам (каналам)
for (const item of items) {
  const data = item.json;

  const url = data.link || '';
  const title = data.title || '';
  // Используем contentSnippet - он уже без HTML
  const description = data.contentSnippet || data.description || data.summary || '';
  // Приоритет isoDate
  const pubDate = data.isoDate || data.pubDate || data.published || data.date || '';

  // Извлекаем имя канала из ссылки t.me/channel_name
  const sourceMatch = url.match(/t\.me\/([^\/]+)/);
  const source = sourceMatch ? sourceMatch[1] : 'Unknown';

  // Пропускаем дубликаты по URL
  if (seenUrls.has(url) || !url) continue;
  seenUrls.add(url);

  // Удаляем служебный текст от FetchRSS в конце описания
  let cleanDescription = description
    .replace(/\(Feed generated with.*?\)$/s, '')
    .replace(/\n{3,}/g, '\n\n') // Убираем лишние переносы строк
    .trim();

  // Создаём или получаем канал с красивым названием
  if (!channelsMap.has(source)) {
    // Берём название из словаря или оставляем как есть
    const displayName = channelNames[source] || source;

    channelsMap.set(source, {
      channel_name: displayName,
      channel_url: `https://t.me/${source}`,
      posts: []
    });
  }

  // Добавляем пост в канал
  channelsMap.get(source).posts.push({
    title: title,
    text: cleanDescription,
    pub_date: formatPubDate(pubDate),
    link: url
  });
}

// Преобразуем Map в массив и сортируем посты по дате (новые первые)
const channels = Array.from(channelsMap.values());
channels.forEach(channel => {
  channel.posts.sort((a, b) => {
    const dateA = new Date(a.pub_date).getTime();
    const dateB = new Date(b.pub_date).getTime();
    return dateB - dateA;
  });
});

// Считаем общее количество постов
const totalPosts = channels.reduce((sum, channel) => sum + channel.posts.length, 0);

// Формируем итоговую структуру
const result = {
  date: formatDate(new Date()),
  channels: channels,
  total_posts: totalPosts,
  total_channels: channels.length
};

// Возвращаем в формате для AI
return [{
  json: result
}];

const items = $input.all();
const twentyFourHoursAgo = Date.now() - 24 * 60 * 60 * 1000;

return items.filter(item => {
  const data = item.json;
  const dateField = data.isoDate || data.pubDate || data.published || data.date;

  if (!dateField) return false;

  try {
    const postTime = new Date(dateField).getTime();
    return !isNaN(postTime) && postTime >= twentyFourHoursAgo;
  } catch {
    return false;
  }
});
